import{_ as e,o as s,c as t,a2 as o}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"Búsqueda por línea de comandos (lff)","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/cli.md","filePath":"es-ES/user-guide/cli.md","lastUpdated":1785993908000}'),i={name:"es-ES/user-guide/cli.md"};function n(l,a,r,d,c,u){return s(),t("div",null,[...a[0]||(a[0]=[o(`<h1 id="busqueda-por-linea-de-comandos-lff" tabindex="-1">Búsqueda por línea de comandos (lff) <a class="header-anchor" href="#busqueda-por-linea-de-comandos-lff" aria-label="Permalink to &quot;Búsqueda por línea de comandos (lff)&quot;">​</a></h1><p>Lertaro también incluye un pequeño complemento de línea de comandos, <strong><code>lff</code></strong> — un buscador difuso al estilo fzf que busca en el mismo índice que ya mantiene la propia App, en lugar de duplicar nada de esa configuración. Es para cualquiera que viva en una terminal y quiera tener también ahí disponible la búsqueda de Lertaro (coincidencia difusa, alias en pinyin, unidades de red, todo), no solo en las ventanas de búsqueda.</p><p><code>lff</code> necesita que la App de Lertaro ya esté en ejecución — se comunica con la App a través de una pipe local, por usuario, en lugar de volver a escanear nada por sí mismo. Si la App no está en ejecución, <code>lff</code> falla de inmediato con un error en stderr en lugar de quedarse colgado.</p><h2 id="configurarlo" tabindex="-1">Configurarlo <a class="header-anchor" href="#configurarlo" aria-label="Permalink to &quot;Configurarlo&quot;">​</a></h2><p><code>lff.exe</code> se instala junto con la App. Marca <strong>Añadir la herramienta de búsqueda por línea de comandos lff al PATH</strong> en la página de selección de tareas del instalador para poder ejecutarlo como <code>lff</code> desde cualquier terminal — esto añade la carpeta de instalación de Lertaro a tu PATH del sistema. Abre una nueva ventana de terminal después; una que ya estuviera abierta cuando instalaste no detectará el cambio.</p><p>Si te saltaste esa opción, aún puedes ejecutarlo directamente desde donde esté instalado Lertaro.</p><h2 id="uso-basico" tabindex="-1">Uso básico <a class="header-anchor" href="#uso-basico" aria-label="Permalink to &quot;Uso básico&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lff</span></span></code></pre></div><p>abre un selector interactivo: escribe para filtrar de forma difusa, exactamente igual que la propia búsqueda de la App — incluida la coincidencia de alias en pinyin para nombres de archivo en chino (ver <a href="./search-syntax.html">Sintaxis de búsqueda</a>).</p><table tabindex="0"><thead><tr><th>Tecla</th><th>Acción</th></tr></thead><tbody><tr><td>Escribir</td><td>Filtrar resultados</td></tr><tr><td>↑ / ↓</td><td>Mover el resaltado</td></tr><tr><td>Re Pág / Av Pág</td><td>Saltar una página cada vez</td></tr><tr><td>← / →</td><td>Mover el cursor de texto dentro de la consulta</td></tr><tr><td>Tab</td><td>Marcar/desmarcar el resultado resaltado (las filas marcadas muestran <code>*</code>)</td></tr><tr><td>Intro</td><td>Imprimir la(s) ruta(s) seleccionada(s) — o solo la resaltada, si no hay ninguna marcada — y salir</td></tr><tr><td>Esc / Ctrl+C</td><td>Salir sin imprimir nada</td></tr></tbody></table><h2 id="rellenar-la-consulta-de-antemano" tabindex="-1">Rellenar la consulta de antemano <a class="header-anchor" href="#rellenar-la-consulta-de-antemano" aria-label="Permalink to &quot;Rellenar la consulta de antemano&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lff report</span></span></code></pre></div><p>y</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>echo report | lff</span></span></code></pre></div><p>ambos se abren ya filtrados a <code>report</code>. En cualquier caso, esto solo rellena de antemano el cuadro de consulta y empieza la misma búsqueda que escribirlo produciría — nunca selecciona ni imprime automáticamente un resultado por sí mismo, así que sigues teniendo que navegar y pulsar Intro/Tab tú mismo.</p><h2 id="seleccionar-varios-resultados" tabindex="-1">Seleccionar varios resultados <a class="header-anchor" href="#seleccionar-varios-resultados" aria-label="Permalink to &quot;Seleccionar varios resultados&quot;">​</a></h2><p>Tab marca o desmarca la fila resaltada. Las filas marcadas persisten incluso después de cambiar la consulta — así que puedes buscar un archivo, marcarlo, buscar otra cosa, marcarla también, y así sucesivamente. La línea de estado muestra cuántos hay marcados en ese momento. Pulsar Intro mientras algo está marcado imprime todas las rutas marcadas, una por línea, sin importar qué esté resaltado en ese momento.</p><h2 id="usar-el-resultado-en-otro-comando" tabindex="-1">Usar el resultado en otro comando <a class="header-anchor" href="#usar-el-resultado-en-otro-comando" aria-label="Permalink to &quot;Usar el resultado en otro comando&quot;">​</a></h2><p>El selector interactivo de <code>lff</code> se dibuja directamente en la consola, nunca a través de los flujos normales de entrada/salida — lo único que llega a stdout es la(s) ruta(s) finalmente seleccionada(s), una por línea, impresas al pulsar Intro. Eso es lo que permite que su salida se combine con las técnicas habituales de la shell para capturar el resultado de otro comando.</p><p>PowerShell:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">code (lff)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lff; code $path</span></span></code></pre></div><p>cmd.exe (sin sustitución de comandos integrada — usa <code>for /f</code>):</p><div class="language-cmd vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmd</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /f </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;delims=&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> %</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">i in (</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&#39;lff&#39;) do code &quot;%i&quot;</span></span></code></pre></div><h2 id="limitaciones" tabindex="-1">Limitaciones <a class="header-anchor" href="#limitaciones" aria-label="Permalink to &quot;Limitaciones&quot;">​</a></h2><ul><li>Sin panel de vista previa — deliberadamente fuera de alcance, ya que el propio <a href="./actions-and-preview.html">Menú de acciones y vista previa</a> de la App ya cubre eso.</li><li>Requiere que la App de Lertaro esté en ejecución; <code>lff</code> no indexa nada por sí mismo.</li></ul>`,25)])])}const m=e(i,[["render",n]]);export{h as __pageData,m as default};
